// Extrair dados da mensagem Evolution API
const data = $input.first().json;

// Verificar se é uma mensagem recebida
if (data.event !== 'messages.upsert') {
  return [];
}

const message = data.data;
const instance = data.instance;

// Extrair informações
const phoneNumber = message.key.remoteJid.replace('@s.whatsapp.net', '');
const messageText = message.message?.conversation || 
                   message.message?.extendedTextMessage?.text || 
                   message.message?.imageMessage?.caption || '';

const messageType = message.message?.imageMessage ? 'image' :
                   message.message?.audioMessage ? 'audio' :
                   message.message?.videoMessage ? 'video' :
                   message.message?.documentMessage ? 'document' : 'text';

return [{
  json: {
    instanceName: instance,
    phoneNumber: phoneNumber,
    messageText: messageText,
    messageType: messageType,
    messageId: message.key.id,
    timestamp: message.messageTimestamp,
    direction: 'received',
    rawData: data
  }
}];

// Analisar mensagem e definir resposta automática
const message = $input.first().json;
const text = message.messageText.toLowerCase();

let response = '';
let action = 'unknown';
let shouldReply = true;

// Palavras-chave e respostas
if (text.includes('agendar') || text.includes('horário') || text.includes('horario')) {
  response = '📅 *Agendamento*\n\n' +
             'Ótimo! Vou te ajudar a agendar.\n\n' +
             'Por favor, me informe:\n' +
             '• Dia desejado (ex: segunda, 15/10)\n' +
             '• Horário preferido\n' +
             '• Serviço (Corte, Barba, Corte + Barba)\n\n' +
             'Ou responda com *HORÁRIOS* para ver disponibilidade.';
  action = 'schedule_request';

} else if (text.includes('horários') || text.includes('horarios') || text.includes('disponibilidade')) {
  response = '🕐 *Horários Disponíveis*\n\n' +
             '📍 Segunda a Sexta: 8h às 18h\n' +
             '📍 Sábado: 8h às 12h\n' +
             '📍 Domingo: Fechado\n\n' +
             'Para agendar, responda com:\n' +
             '*DIA + HORÁRIO*\n\n' +
             'Exemplo: "Segunda 14h"';
  action = 'show_availability';

} else if (text.includes('preço') || text.includes('preco') || text.includes('valor') || text.includes('quanto')) {
  response = '💰 *Tabela de Preços*\n\n' +
             '✂️ Corte Masculino: R$ 25\n' +
             '✂️ Corte Feminino: R$ 35\n' +
             '🧔 Barba: R$ 15\n' +
             '✨ Corte + Barba: R$ 35\n\n' +
             '🎉 *PROMOÇÃO*\n' +
             'Combo Corte + Barba por apenas R$ 30!\n\n' +
             'Digite *AGENDAR* para marcar seu horário!';
  action = 'show_prices';

} else if (text.includes('confirmar') || text.includes('confirmo') || text.includes('sim')) {
  response = '✅ *Agendamento Confirmado!*\n\n' +
             'Seu horário está reservado! 🎉\n\n' +
             'Vou te enviar um lembrete 1 hora antes.\n\n' +
             'Se precisar cancelar ou reagendar, é só me avisar.\n\n' +
             'Até breve! 👋';
  action = 'confirm_appointment';

} else if (text.includes('cancelar') || text.includes('desmarcar')) {
  response = '❌ *Cancelamento*\n\n' +
             'Seu agendamento foi cancelado.\n\n' +
             'Quando quiser marcar novamente, é só me chamar! 😊';
  action = 'cancel_appointment';

} else if (text.includes('localização') || text.includes('localizacao') || text.includes('endereço') || text.includes('endereco') || text.includes('onde')) {
  response = '📍 *Nossa Localização*\n\n' +
             'Rua Exemplo, 123 - Centro\n' +
             'São Paulo - SP\n\n' +
             '🚗 Estacionamento gratuito\n' +
             '♿ Acessível\n\n' +
             'Ver no mapa: [link do Google Maps]';
  action = 'show_location';

} else if (text.includes('oi') || text.includes('olá') || text.includes('ola') || text.includes('bom dia') || text.includes('boa tarde') || text.includes('boa noite')) {
  response = '👋 *Olá! Bem-vindo!*\n\n' +
             'Eu sou o assistente virtual da barbearia.\n\n' +
             'Como posso te ajudar hoje?\n\n' +
             '• Digite *AGENDAR* para marcar horário\n' +
             '• Digite *PREÇOS* para ver valores\n' +
             '• Digite *LOCALIZAÇÃO* para nosso endereço\n' +
             '• Digite *HORÁRIOS* para disponibilidade';
  action = 'welcome';

} else {
  response = '🤔 Desculpe, não entendi sua mensagem.\n\n' +
             'Tente:\n' +
             '• *AGENDAR* - Para marcar horário\n' +
             '• *PREÇOS* - Ver tabela de preços\n' +
             '• *HORÁRIOS* - Ver disponibilidade\n' +
             '• *LOCALIZAÇÃO* - Nosso endereço\n\n' +
             'Ou fale com um atendente humano! 👨‍💼';
  action = 'unknown';
}

return [{
  json: {
    ...message,
    response: response,
    action: action,
    shouldReply: shouldReply
  }
}];
